#!/usr/bin/env python3
"""Freeze the CMF-confirmed daily channel breakout experiment before evaluation."""
import hashlib,json,subprocess,sys
from datetime import datetime,timezone
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];R=Path(__file__).resolve().parent
sys.path.insert(0,str(ROOT/'research/automation'));import registry
PIN='4e8f986601e8e0fafb15c521dcfd9d657dc7ccc2'
DATA={a:[ROOT/f'data/normalized/binance/{a}/binance_{a}_20240916T000000Z_20250916T000000Z_transfer_20261001/spot_bars.parquet',ROOT/f'data/normalized/binance/{a}/binance_{a}_20250916T000000Z_20260916T000000Z_archive_20260929/spot_bars.parquet'] for a in ('BTC','ETH')}
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def utc():return datetime.now(timezone.utc).isoformat().replace('+00:00','Z')
raw=R/'exchange_info_raw.json';meta=json.loads(raw.read_text());assert {x['symbol'] for x in meta['symbols']}=={'BTCUSDT','ETHUSDT'} and all(x['status']=='TRADING' and x.get('isSpotTradingAllowed',True) for x in meta['symbols'])
files={a:[{'path':str(p.relative_to(ROOT)),'sha256':sha(p),'bytes':p.stat().st_size} for p in ps] for a,ps in DATA.items()}
start='2025-09-19T00:01:00Z';end='2026-09-14T00:01:00Z'
logic={
 'entry':'At each completed UTC daily close t, require close[t] strictly greater than max(high[t-E:t]); the E prior daily bars exclude the compared signal-day bar. Also require CMF_N[t] strictly greater than 0.05. If both pass and the sleeve is flat, desire long.',
 'exit':'At each completed UTC daily close t, exit an existing long when close[t] is strictly less than min(low[t-30:t]); the 30 prior bars exclude the compared signal-day bar. CMF is entry confirmation only; it never independently exits.',
 'cmf':'For each completed bar j, multiplier=(2*close[j]-high[j]-low[j])/(high[j]-low[j]); use 0 when high==low. money_flow_volume=multiplier*quote_volume[j]. CMF_N[t]=sum(money_flow_volume[t-N+1:t+1])/sum(quote_volume[t-N+1:t+1]); return 0 if denominator is 0. The signal bar is included because its full OHLCV is available at its close. Raw range is [-1,+1]; no *100 scaling.',
 'execution':'Signal availability is daily bar open time + 86400000ms. Execute any state change only at the next UTC day 00:01 1-minute bar open, after the daily close is available. OOS begins with cash at 2025-09-19 00:01 UTC and ends by terminal liquidation at 2026-09-14 00:01 UTC. Never fill at the signal close or past historical price after a delayed decision.',
 'allocation':'One 2,000 USDT portfolio with independent BTC and ETH long-only sleeves, raw initial weights 0.50/0.50 (1,000 USDT each). No leverage, shorting, interest, cross-sleeve transfers or rebalancing. A sleeve holds only its own coin plus residual USDT.',
 'close_channel':'Entry and exit extrema are computed solely from completed bars before t; the signal-day close/high/low are never included in the channel being compared.'}
costs={'fee_per_side':0.001,'estimated_half_spread_per_side':0.0001,'slippage_per_side':0.0002,'impact':'0.5 * sample standard deviation of previous 20 complete daily log returns * sqrt(order quote budget / mean quote volume of previous 20 complete UTC days)','maximum_ADV_participation':0.001,'multipliers':[1,2,3],'all_cost_terms_scaled_together':True,'cash_yield':0}
plan={'round':R.name,'frozen_at_utc':utc(),'status':'frozen_before_evaluation','source_repository_commit':subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),'source_pin':PIN,'direction':'Daily channel breakout confirmed by Chaikin Money Flow, separate BTC/ETH cash sleeves','hypothesis':'A breakout that closes in the upper part of its daily range on volume-weighted accumulation may filter low-quality price-only breakouts. This is a testable hypothesis, not an asserted edge; the indicator and thresholds are fixed before results.', 'literature_context':[{'source':'TA-Lib CMF indicator definition and implementation spec','url':'https://ta-lib.org/functions/cmf.html','accessed_utc':utc(),'scope':'Defines the money-flow multiplier and trailing-volume-normalized CMF calculation; does not validate this BTC/ETH trading rule.'},{'source':'Marc Chaikin, The Birth of Chaikin Money Flow','url':'https://chaikinanalytics.com/powerfeed/articles/the-birth-of-chaikin-money-flow','accessed_utc':utc(),'scope':'Origin context for weighting close location inside the high-low range by trading volume; not evidence of crypto profitability.'}], 'prior_work':{'initial16_audit':'research/experiments/20261012T035429Z/prior_evidence_audit.json records actual backtest evidence for all 16 initial entries; no initial result-available=false research spec is eligible for backfill.','unavailable_registry_rows':'The 58 unresolved latest rows are 40 paper-live-portfolio-observation blocked rows owned by btc-eth-2 and 18 abandoned lead-lag drafts; they are not missing initial research backtests and will be left unchanged.','related_families':'Existing close-channel, OBV/SMA, volume-confirmed-channel, volatility-compression, lead-lag and momentum families were reviewed. CMF uses volume-weighted close location within each completed bar; it is economically distinct from OBV sign accumulation, though all are related volume confirmation research and share historical-selection limitations.','historical_selection':'The 2025-09-19..2026-09-14 window is repeatedly reused development/OOS history and is not an untouched holdout.'},'data':{'exchange':'Binance spot archived 1-minute OHLCV, aggregated to UTC daily OHLCV; timestamps and closed flags must be continuous and all OOS closes completed before decision.','assets':files,'exchange_info_raw_path':str(raw.relative_to(ROOT)),'exchange_info_raw_sha256':sha(raw),'start_utc':start,'end_exclusive_utc':end,'oos_days':360,'folds':12,'fold_days':30,'history_reused':True,'holdout_note':'OOS data have been repeatedly searched; not a final holdout.'},'portfolio':{'capital_usdt':2000,'raw_initial_weights':[0.5,0.5],'sleeve_cash_usdt':{'BTC':1000,'ETH':1000},'transfer_or_normalization':False,'leverage':False},'rule':logic,'grid':{'entry_lookback_days':[10,20,40],'cmf_lookback_days':[10,20,40],'cmf_entry_threshold':0.05,'exit_lookback_days':30,'assets':['BTC','ETH'],'sensitivity':'Full predeclared 3x3 entry-lookback by CMF-lookback grid; the two varied axes are independent; all nine combinations retained.'},'cost_model':costs,'exchange_snapshot':{'captured_at_utc':datetime.fromtimestamp(meta['serverTime']/1000,timezone.utc).isoformat().replace('+00:00','Z'),'raw_path':str(raw.relative_to(ROOT)),'raw_sha256':sha(raw),'filters':'PRICE_FILTER, LOT_SIZE, NOTIONAL, and PERCENT_PRICE_BY_SIDE from current Binance spot exchangeInfo; historical percent-price reference approximated using prior five completed 1-minute closes.'},'time_splits':{'oos_start_utc':start,'oos_end_exclusive_utc':end,'folds':12,'fold_days':30,'folds_contiguous':True,'signal_warmup_uses_only_prior_complete_daily_bars':True},'failure_gates':{'all_1x_2x_3x_net_returns_positive':True,'minimum_positive_1x_folds':8,'folds':12,'maximum_3x_sampled_drawdown_pct':25,'minimum_3x_local_neighbor_positive_fraction':0.60,'minimum_gross_reference_pnl_to_cost':2.5,'rejected_capacity_or_exchange_filter_orders':0,'terminal_flat_all_cost_scenes':True},'benchmark_read_only':{'source_report':'research/experiments/20261013T224056Z/report.json','configuration':'hold_360d_BTC_ETH_50_50_monthly_volmanaged','note':'Read-only exact same dates, independent 1,000-USDT sleeves and costs; no repeated benchmark evaluation in this batch.'},'prior_registry_snapshot':{'events':len(registry.read_events(ROOT/'research/automation/registry.jsonl')),'unique_fingerprints':len(registry.read_records(ROOT/'research/automation/registry.jsonl'))}}
plan['_sha256']=registry.digest(plan)
(R/'plan.json').write_text(json.dumps(plan,indent=2,ensure_ascii=False)+'\n')
batch=[];prior=registry.read_records(ROOT/'research/automation/registry.jsonl');fps=set()
for entry in (10,20,40):
 for n in (10,20,40):
  name=f'cmf_channel_E{entry}_N{n}_T05'
  spec={'kind':'strategy','family':'spot-daily-cmf-confirmed-channel-breakout-paired-sleeves','market':'spot','universe':['BTC/USDT','ETH/USDT'],'timeframe':'1d','logic':logic,'parameters':{'channel_entry_lookback_days':entry,'cmf_lookback_days':n,'cmf_entry_threshold':0.05,'channel_exit_lookback_days':30,'capital_usdt':2000,'raw_initial_weights':{'BTC':0.5,'ETH':0.5},'sleeve_cash_usdt':{'BTC':1000,'ETH':1000},'start_utc':start,'end_exclusive_utc':end,'folds':12,'fold_days':30,'fee_per_side':0.001,'estimated_half_spread_per_side':0.0001,'slippage_per_side':0.0002,'maximum_ADV_participation':0.001,'cost_multipliers':[1,2,3],'exchange_info_raw_sha256':sha(raw)},'validation_plan':str((R/'plan.json').relative_to(ROOT)),'name':name}
  fp=registry.fingerprint(spec);assert fp not in fps and not (prior.get(fp) and prior[fp].get('result_available') is True),name;fps.add(fp)
  path=R/'specs'/f'{name}.json';path.parent.mkdir(exist_ok=True);path.write_text(json.dumps(spec,indent=2,ensure_ascii=False)+'\n');batch.append({'name':name,'spec':str(path.relative_to(ROOT)),'role':'candidate'})
(R/'batch.json').write_text(json.dumps(batch,indent=2,ensure_ascii=False)+'\n')
print(json.dumps({'frozen':True,'plan_sha256':sha(R/'plan.json'),'candidate_configs':len(batch),'initial16_missing':0,'registry_events_before':plan['prior_registry_snapshot']['events'],'exact_duplicates':0}))
